import numpy as np


def q456(reward_sums, counts, exploration=2):
    counts = np.asarray(counts)
    sums = np.asarray(reward_sums)
    missing = np.flatnonzero(counts == 0)
    if len(missing):
        return int(missing[0])
    return int(
        np.argmax(
            sums / counts
            + np.sqrt(exploration * np.log(counts.sum()) / counts)
        )
    )
